import sys

from defusedxml.minidom import parse

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

doc = parse("unpacked/word/document.xml")

# Map styleId -> style name from styles.xml
styles = {}
try:
    sdoc = parse("unpacked/word/styles.xml")
    for st in sdoc.getElementsByTagNameNS(W, "style"):
        sid = st.getAttributeNS(W, "styleId")
        name_el = st.getElementsByTagNameNS(W, "name")
        name = name_el[0].getAttributeNS(W, "val") if name_el else ""
        styles[sid] = name
except Exception as e:
    print("styles.xml parse error:", e)

print("STYLE ID -> NAME MAPPING:")
for sid, name in sorted(styles.items()):
    print(f"  {sid!r} -> {name!r}")

def para_text(p):
    texts = []
    for t in p.getElementsByTagNameNS(W, "t"):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    for t in p.getElementsByTagNameNS(W, "delText"):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(texts)

print("\nPARAGRAPHS:")
body = doc.getElementsByTagNameNS(W, "body")[0]
for i, p in enumerate(body.getElementsByTagNameNS(W, "p")):
    ppr = p.getElementsByTagNameNS(W, "pPr")
    style_val = None
    if ppr:
        pstyle = ppr[0].getElementsByTagNameNS(W, "pStyle")
        if pstyle:
            style_val = pstyle[0].getAttributeNS(W, "val")
    text = para_text(p).strip()
    if style_val or text:
        print(f"[{i}] style={style_val!r} text={text[:120]!r}")

